CREATE OR REPLACE FUNCTION invento.check_journal()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE jid uuid; cnt integer; currencies integer; net numeric;
BEGIN
 IF TG_TABLE_NAME='journal_entries' THEN jid := NEW.id;
 ELSE jid := NEW."journalEntryId"; END IF;
 SELECT count(*), count(DISTINCT a.currency), sum(CASE p.side WHEN 'credit' THEN p."amountMinor" ELSE -p."amountMinor" END)
 INTO cnt,currencies,net FROM invento.postings p JOIN invento.ledger_accounts a ON a.id=p."ledgerAccountId" WHERE p."journalEntryId"=jid;
 IF cnt<2 OR currencies<>1 OR net<>0 THEN RAISE EXCEPTION 'unbalanced_journal'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION invento.nonnegative_customer_balance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE balance numeric; customer boolean;
BEGIN
 SELECT purpose='customer' INTO customer FROM invento.ledger_accounts WHERE id=NEW."ledgerAccountId";
 IF customer THEN
  SELECT sum(CASE side WHEN 'credit' THEN "amountMinor" ELSE -"amountMinor" END) INTO balance FROM invento.postings WHERE "ledgerAccountId"=NEW."ledgerAccountId";
  IF balance<0 THEN RAISE EXCEPTION 'negative_customer_balance'; END IF;
 END IF;
 RETURN NEW;
END $function$
